// deb, rpm and apk against their own tools (testdata/oracle, generated by scripts/oracle) and against
// the tool-generated osv-scalibr vectors.
import { describe, expect, it } from 'vitest'
import { contains, getScheme, normalizeVers, type Scheme, stringifyVers } from '../../src/index.ts'
import { expectTotalOrder, oracleValidity, SIGN } from '../support/oracle.ts'
import { loadComparisonPairs } from '../support/vectors.ts'

function scheme(type: string): Scheme {
  return getScheme(type) as Scheme
}

for (const [eco, tool] of [
  ['deb', 'dpkg'],
  ['rpm', 'rpm'],
  ['apk', 'apk-tools'],
] as const) {
  describe(`${eco} against ${tool}`, () => {
    const s = scheme(eco)
    const valid = oracleValidity(eco)

    it('agrees on validity', () => {
      const wrong = valid
        .filter(([v, ok]) => s.isValid(v) !== ok)
        .map(([v, ok]) => `${v} (${tool}: ${ok ? 'valid' : 'invalid'})`)
      expect(wrong).toEqual([])
    })

    it('agrees on every comparison', () => {
      const wrong = loadComparisonPairs(`oracle/${eco}.txt`)
        .filter(({ a, op, b }) => Math.sign(s.compare(a, b)) !== SIGN[op])
        .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
      expect(wrong).toEqual([])
    })

    it('is a total order', () => {
      const sample = valid.filter(([, ok]) => ok).map(([v]) => v)
      expectTotalOrder(
        s,
        sample.filter((_, i) => i % Math.ceil(sample.length / 400) === 0),
      )
    })
  })
}

describe('osv-scalibr generated vectors', () => {
  for (const [eco, file] of [
    ['deb', 'debian-versions.txt'],
    ['deb', 'debian-versions-generated.txt'],
    ['apk', 'alpine-versions-generated.txt'],
  ] as const) {
    it(`${eco}: ${file}`, () => {
      const s = scheme(eco)
      const pairs = loadComparisonPairs(`osv-scalibr/${file}`)
      const usable = pairs.filter(({ a, b }) => s.isValid(a) && s.isValid(b))
      const wrong = usable
        .filter(({ a, op, b }) => Math.sign(s.compare(a, b)) !== SIGN[op])
        .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
      expect(wrong).toEqual([])
      expect(usable.length).toBeGreaterThan(pairs.length * 0.95)
    })
  }
})

describe('containment', () => {
  it.each([
    ['vers:deb/>=1.2.3-1|<1.2.3-4~bpo11', '1.2.3-2', true],
    ['vers:deb/>=1.2.3-1|<1.2.3-4~bpo11', '1.2.3-4', false],
    ['vers:deb/<1.0', '1.0~rc1', true],
    ['vers:deb/<1:0.1', '9.9', true],
    ['vers:deb/1.0', '1.0-0', true],
    ['vers:rpm/<1.0.1', '1.0^git1', true],
    ['vers:rpm/>=1.0|<1.0.1', '1.0^git1', true],
    ['vers:rpm/>=1:1.0', '2.0', false],
    ['vers:rpm/<1.0-1', '1.0', true],
    ['vers:apk/<1.2', '1.2_rc1', true],
    ['vers:apk/<1.2', '1.2_p1', false],
    ['vers:apk/>=1.2-r0|<1.2-r3', '1.2-r2', true],
  ] as const)('%s contains %s: %s', (range, version, expected) => {
    expect(contains(range, version)).toBe(expected)
  })

  it('sorts constraints by the ecosystem order when normalising', () => {
    expect(stringifyVers(normalizeVers('vers:deb/<1.0|>=1.0~rc1'))).toBe('vers:deb/>=1.0~rc1|<1.0')
    expect(stringifyVers(normalizeVers('vers:rpm/1.0.1|1.0^git1|1.0'))).toBe(
      'vers:rpm/1.0|1.0^git1|1.0.1',
    )
    expect(stringifyVers(normalizeVers('vers:apk/1.2|1.2_p1|1.2_rc1'))).toBe(
      'vers:apk/1.2_rc1|1.2|1.2_p1',
    )
  })
})

describe('README examples', () => {
  it('match', () => {
    expect(contains('vers:deb/>=1.2.3-1|<1.2.3-4~bpo11', '1.2.3-2')).toBe(true)
    expect(scheme('rpm').compare('1.0^git1', '1.0.1')).toBeLessThan(0)
    expect(scheme('apk').compare('1.2_rc1', '1.2')).toBeLessThan(0)
  })
})
